-- RB-05 HR core: the HR capability flag on users, employee records, encrypted tier 2 and tier 3 data, and the
-- append-only HR audit log. Additive only: existing users get is_hr = 0, no table is rebuilt. Employee data never
-- enters pages_fts or tasks_fts. Generated by drizzle-kit, then hand-edited: the column CHECK on is_hr and the
-- append-only triggers below are not expressible in schema.ts.
ALTER TABLE `users` ADD `is_hr` integer DEFAULT 0 NOT NULL CHECK (`is_hr` IN (0, 1));
--> statement-breakpoint
CREATE TABLE `employee_compensation` (
	`id` text PRIMARY KEY NOT NULL,
	`employee_id` text NOT NULL,
	`effective_on` text NOT NULL,
	`amount_enc` text NOT NULL,
	`currency` text DEFAULT 'IDR' NOT NULL,
	`note_enc` text,
	`key_version` integer DEFAULT 1 NOT NULL,
	`created_by` text NOT NULL,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`employee_id`) REFERENCES `employees`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "employee_compensation_currency_check" CHECK("employee_compensation"."currency" in ('IDR'))
);
--> statement-breakpoint
CREATE INDEX `employee_compensation_employee_idx` ON `employee_compensation` (`employee_id`,`effective_on`);--> statement-breakpoint
