CREATE TABLE `employees` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`employee_no` text,
	`full_name` text NOT NULL,
	`preferred_name` text,
	`job_title` text,
	`department` text,
	`location` text,
	`work_email` text,
	`work_phone` text,
	`manager_id` text,
	`employment_type` text NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`start_on` text,
	`probation_ends_on` text,
	`end_on` text,
	`created_by` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`deleted_at` integer,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`manager_id`) REFERENCES `employees`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "employees_type_check" CHECK("employees"."employment_type" in ('permanent', 'contract', 'probation', 'intern', 'part_time')),
	CONSTRAINT "employees_status_check" CHECK("employees"."status" in ('active', 'terminated'))
);
