-- INSERT OR REPLACE deletes the old row without firing DELETE triggers; refusing an insert of an existing id keeps
-- both tables append-only against REPLACE too (red team RB-05 L2).
CREATE TRIGGER `hr_audit_log_no_replace` BEFORE INSERT ON `hr_audit_log`
WHEN EXISTS (SELECT 1 FROM `hr_audit_log` WHERE `id` = NEW.`id`) BEGIN
	SELECT RAISE(ABORT, 'hr_audit_log is append-only');
END;
--> statement-breakpoint
CREATE TRIGGER `employee_compensation_no_replace` BEFORE INSERT ON `employee_compensation`
WHEN EXISTS (SELECT 1 FROM `employee_compensation` WHERE `id` = NEW.`id`) BEGIN
	SELECT RAISE(ABORT, 'employee_compensation is append-only');
END;
